import os
import zipfile
import tempfile
from flask import Flask, request, Response

app = Flask(__name__)

@app.route('/convert', methods=['POST'])
def convert():
    if 'file' not in request.files:
        return Response("Missing file part", status=400)
    file = request.files['file']
    if file.filename == '':
        return Response("No selected file", status=400)
    if not file.filename.endswith('.zip'):
        return Response("File must be a zip archive", status=400)

    try:
        with tempfile.TemporaryDirectory() as tmpdir:
            zip_path = os.path.join(tmpdir, file.filename)
            file.save(zip_path)
            output_lines = []
            with zipfile.ZipFile(zip_path, 'r') as z:
                for name in z.namelist():
                    if name.endswith('.txt') or name.endswith('.text'):
                        try:
                            with z.open(name) as f:
                                content = f.read().decode('utf-8', errors='replace')
                                output_lines.append(content)
                        except Exception as e:
                            return Response(f"Error reading {name}: {str(e)}", status=400)
            if not output_lines:
                return Response("No text files found in zip", status=400)
            output = '\n'.join(output_lines)
            return Response(output, mimetype='text/plain')
    except zipfile.BadZipFile:
        return Response("Invalid zip file", status=400)
    except Exception as e:
        return Response(f"Server error: {str(e)}", status=500)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
